import{z as B,x as n,o as r,c as p,q as A,j as l,D as e,d as D,s as t,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"内核旁路：DPDK 与 AF_XDP","description":"","frontmatter":{"title":"内核旁路：DPDK 与 AF_XDP","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hpc-kernel-bypass.md","filePath":"cs/hpc-kernel-bypass.md","lastUpdated":1791413859000}'),o={name:"cs/hpc-kernel-bypass.md"};function d(P,a,m,u,F,h){const s=n("Mermaid");return r(),p("div",null,[a[2]||(a[2]=A('<h1 id="内核旁路-dpdk-与-af-xdp" tabindex="-1">内核旁路：DPDK 与 AF_XDP <a class="header-anchor" href="#内核旁路-dpdk-与-af-xdp" aria-label="Permalink to &quot;内核旁路：DPDK 与 AF_XDP&quot;">​</a></h1><div class="epigraph"><p>包率把每包预算压进几百纳秒后，优化路径的尽头是缩短路径：把协议栈从数据面上拿掉。</p><footer>—— 据 DPDK 官方文档；Linux 内核 AF_XDP 文档整理</footer></div><p><a href="/cs/hpc-io-uring">上一课</a>把陷入摊销到共享环上，但每个包仍要完整走过内核协议栈：中断、软中断、skb 分配、逐层解析。主干已有<a href="/cs/dpdk-kernel-bypass">内核旁路 DPDK</a> 与 <a href="/cs/xdp-ebpf">XDP 与 eBPF 网络</a>两课，分别钉了用户态轮询与驱动层 eBPF 的机制；本课把两者放进同一张账：完整旁路与折中旁路各自的真实成本、各自的失败方式，以及低延迟业务怎么选。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>先算预算：64 字节小包在 10 GbE 线速约 14.88 Mpps，均摊每包不足 70 ns，而一次跨核缓存失效就是几十纳秒量级——内核路径每包的中断处理与协议栈工作远超此数，栈本身成了最大单项成本。DPDK 是完整旁路：VFIO 把网卡寄存器映射进用户态，PMD 线程以轮询代替中断，描述符环与缓冲建在 hugepage 上，数据面里没有内核。AF_XDP 是折中旁路：XDP 程序在驱动层分诊，需要旁路的帧经 umem 环直进用户态，其余交回内核栈，网卡管理、过滤与统计仍由内核承担。不这么做会错在哪：把旁路当提速开关而保持「每包一次处理」的代码结构，批处理与核亲和的收益全部丢失；或者忘了轮询在低包率时段烧满核——旁路方案在深夜低峰可能比中断更贵。</p><p><span class="marginnote">常见误区：初学者容易以为「装上 DPDK 就快了」。实际上旁路收益的大头是配套的写法——一次收一批、每个核只碰自己的队列。代码结构不改，旁路只是把慢路径原样搬进用户态，收益所剩无几。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>DPDK 侧的流水线：网卡绑到 vfio-pci → mempool 与收发环建在 hugepage → RSS 把流散到多队列，每核一条 PMD 绑一个队列 → 主循环一次 burst 收 32 或 64 包，批内摊销。AF_XDP 侧：加载 XDP 程序做分诊，XSK 的 umem 以 fill/completion 与 RX/TX 双组环推进，生产者-消费者语义由内存序保证；不需要的包 redirect 回内核，保住既有协议栈与工具链。选型判据三条：核能否专用、要不要内核服务、目标包率离线速多远。量化栏的<a href="/quant/colocation-microwave">主机托管与微波</a>把物理距离当延迟预算建模；内核旁路是同一逻辑在机器内部的一层——路径每长一截，账上就多一项。</p>',8)),(r(),l(i,null,{default:e(()=>[t(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NIC%5B%22%E7%BD%91%E5%8D%A1%20RX%20%E9%98%9F%E5%88%97%22%5D%20--%3E%20RSS%5B%22RSS%20%E6%95%A3%E5%88%97%E5%88%B0%E5%A4%9A%E9%98%9F%E5%88%97%22%5D%0A%20%20RSS%20--%3E%20PMD%5B%22DPDK%EF%BC%9APMD%20%E8%BD%AE%E8%AF%A2%20burst%20%E6%94%B6%E5%8C%85%22%5D%0A%20%20PMD%20--%3E%20US%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E6%95%B0%E6%8D%AE%E9%9D%A2%22%5D%0A%20%20RSS%20--%3E%20XD%5B%22XDP%20%E7%A8%8B%E5%BA%8F%E5%88%86%E8%AF%8A%22%5D%0A%20%20XD%20--%3E%7C%E9%9C%80%E8%A6%81%E6%97%81%E8%B7%AF%7C%20UM%5B%22umem%20%E7%8E%AF%E7%9B%B4%E8%BF%9B%E7%94%A8%E6%88%B7%E6%80%81%22%5D%0A%20%20XD%20--%3E%7C%E6%99%AE%E9%80%9A%E6%B5%81%E9%87%8F%7C%20KS%5B%22%E5%86%85%E6%A0%B8%E5%8D%8F%E8%AE%AE%E6%A0%88%22%5D%0A%20%20UM%20--%3E%20US%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[D(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[D("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"省下来的不只是系统调用：是每包两次跨越用户/内核边界的拷贝与缓存失效，是中断聚合在高包率下反而添上的延迟抖动——旁路方案常直接关掉聚合，用轮询的确定性换掉抖动。批处理把每包固定成本摊到整批；队列与核一一对应消灭锁与跨核迁移。代价同样是机制性的：核被独占后与调度器的协作消失；内核统计看不见了，可观测性要自建；漏洞与升级路径收窄。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"轮询与中断可以用外卖打比方：中断是外卖到了按门铃（平时能干别的，但每单都打断你一次），轮询是你站在门口盯着（一响就拿到，但没单时人也耗在那）。深夜没几单时，站门口干等反而比按门铃贵——这就是低包率时段轮询更贵的直觉。"),D("AF_XDP 折中的定价清单：多付一次 XDP 程序执行与 umem 环形管理，换回内核服务与可移植性——两课主干机制在此互补而非竞争。")],-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"10 GbE 64 字节线速 \\(\\approx 14.88\\) Mpps：\\(10^{10}/((64+20)\\times 8)\\)，加的 20 字节是前导与帧间隙。每包 70 ns 的预算里，批处理与缓存亲和不是优化项，是及格线。")],-1)),a[7]||(a[7]=E("p",null,"旁路到底省掉了哪几步？把两条路径并排摊开看：",-1)),(r(),l(i,null,{default:e(()=>[t(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20K%5B%22%E4%BC%A0%E7%BB%9F%E5%86%85%E6%A0%B8%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20IRQ%5B%22%E7%BD%91%E5%8D%A1%E7%A1%AC%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20SOFT%5B%22%E8%BD%AF%E4%B8%AD%E6%96%AD%E8%B0%83%E5%BA%A6%22%5D%0A%20%20%20%20SOFT%20--%3E%20SKB%5B%22%E5%88%86%E9%85%8D%20skb%E3%80%81%E9%80%90%E5%B1%82%E8%A7%A3%E6%9E%90%22%5D%0A%20%20%20%20SKB%20--%3E%20CPY%5B%22%E6%8B%B7%E8%B4%9D%E5%88%B0%E7%94%A8%E6%88%B7%E7%BC%93%E5%86%B2%22%5D%0A%20%20end%0A%20%20subgraph%20U%5B%22DPDK%20%E6%97%81%E8%B7%AF%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20POLL%5B%22PMD%20%E7%BA%BF%E7%A8%8B%E8%BD%AE%E8%AF%A2%22%5D%20--%3E%20DESC%5B%22%E8%AF%BB%E6%8F%8F%E8%BF%B0%E7%AC%A6%E7%8E%AF%E6%88%90%E6%89%B9%E6%94%B6%E5%8C%85%22%5D%0A%20%20%20%20DESC%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%E7%9B%B4%E6%8E%A5%E8%AF%BB%20hugepage%20%E7%BC%93%E5%86%B2%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[D(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写 XDP 程序的 verifier 与 map 机制（<a href="/cs/xdp-ebpf">XDP 与 eBPF 网络</a>已钉），不写 DPDK 的 vhost/virtio 虚拟化数据面（<a href="/cs/paravirtualization">半虚拟化</a>的对象），不写具体转发应用。跨机之后还剩什么：两端的 TCP、上下文与拷贝仍在——RDMA 是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>线速把每包预算压进几十纳秒，内核协议栈本身成为最大单项成本。</li><li>DPDK 完整旁路换线速与窄延迟分布，卖掉核的可复用与内核服务；AF_XDP 折中保留内核，多付一次分诊。</li><li>旁路收益的大头是批处理与核队列亲和，不是「省掉的系统调用」。</li><li>低包率时轮询更贵、零拷贝未必更快；旁路是负载形态的函数，不是无条件的快。</li><li>出处：DPDK 官方文档；Linux 内核 AF_XDP/XDP 文档。</li></ul><p><span class="marginnote">给「核被独占」一个数字感受：一台 64 核机器给 DPDK 专派 4 个核，等于永远烧掉约 6% 的 CPU——哪怕半夜一个包都没有。所以选型前先问：这几个核拿去跑别的业务值多少钱，和延迟收益怎么比。</span></p>',5))])}const S=B(o,[["render",d]]);export{c as __pageData,S as default};
